  if (g.blockAt(3, 1, 3) !== "minecraft:bricks" || !out.refused.some(([x, y, z]) => x === 3 && y === 1 && z === 3)) fails.push("pier_line overwrote an existing block");
}

if (fails.length) {
  console.error(fails.join("\n"));
  process.exit(1);
}
console.log("h4 ok");

